package cn.huankan.event;
import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AiEvidenceValidatorTest {
 private final ObjectMapper json=new ObjectMapper();
 private com.fasterxml.jackson.databind.node.ObjectNode output(){var o=json.createObjectNode();o.putArray("extracted_facts");o.putArray("hypotheses");o.putArray("uncertainties").add("尚需人工核查");o.putArray("counter_evidence");return o;}
 @Test void exactNumbersAndUnitsRequireLiteralProof(){var o=output();o.withArray("extracted_facts").addObject().put("evidence_id","proof").put("quote","GDP rose 2.5 percent year-on-year").put("claim","GDP rose 2.5 percent").put("value","2.5").put("unit","percent").put("value_kind","YOY");assertTrue(AiEvidenceValidator.validate(o,Map.of("proof","GDP rose 2.5 percent year-on-year")).passed());o.withArray("extracted_facts").get(0).deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)o.withArray("extracted_facts").get(0)).put("claim","GDP rose 5 percent");assertFalse(AiEvidenceValidator.validate(o,Map.of("proof","GDP rose 2.5 percent year-on-year")).passed());}
 @Test void fabricatedSummaryAndToolsCannotPass(){var o=output();o.put("summary","收益 99%");assertFalse(AiEvidenceValidator.validate(o,Map.of()).passed());o.remove("summary");o.putArray("tool_calls");assertFalse(AiEvidenceValidator.validate(o,Map.of()).passed());}
 @Test void wrongCurrencyDateAndComparisonCannotPass(){var o=output();o.withArray("extracted_facts").addObject().put("evidence_id","proof").put("quote","USD 2.5 million on 2026-10-01").put("claim","USD 2.5 million").put("value","2.5").put("unit","million").put("currency","EUR").put("observation_date","2026-10-02").put("value_kind","MOM");assertFalse(AiEvidenceValidator.validate(o,Map.of("proof","USD 2.5 million on 2026-10-01")).passed());}
 @Test void rssScopeDoesNotMixArticles(){String xml="<rss><item><title>First</title><link>https://example.invalid/1</link></item><item><title>Second</title><link>https://example.invalid/2</link></item></rss>";String scope=AiResearchService.scope(xml,"Second","https://example.invalid/2");assertFalse(scope.contains("First"));assertTrue(scope.contains("Second"));assertThrows(IllegalStateException.class,()->AiResearchService.scope(xml,"missing","missing"));}
 @Test void percentagePointsCannotBecomePercentAndCompanyIdentityCannotBeInvented(){var o=output();var f=o.withArray("extracted_facts").addObject().put("evidence_id","proof").put("quote","Rate increased 0.5 percentage points").put("claim","Rate increased 0.5 percent").put("value","0.5").put("unit","percent");assertFalse(AiEvidenceValidator.validate(o,Map.of("proof","Rate increased 0.5 percentage points")).passed());f.put("unit","percentage points").put("claim","Rate increased 0.5 percentage points");assertTrue(AiEvidenceValidator.validate(o,Map.of("proof","Rate increased 0.5 percentage points")).passed());f.put("company_identifier","INVENTED_LEI");assertFalse(AiEvidenceValidator.validate(o,Map.of("proof","Rate increased 0.5 percentage points")).passed());}
}
